      jest
        .spyOn(client.search, 'characterSearch')
        .mockResolvedValue(expectedResults as any);
    });

    when('characterSearch is called with the search term', async () => {
      result = await client.search.characterSearch(
        characterId,
        searchString,
        allCategories as any,
      );
    });

    then('the client shall return results containing matching character IDs', () => {
      expect(result).toBeDefined();
      expect(result.character).toHaveLength(3);
      expect(result.character).toContain(1689391488);
    });
  });

  test('WHEN characterSearch is called with a broad query, the client shall return results across multiple categories', ({
    given,
    when,
    then,
  }) => {
    let result: any;
    const characterId = 90000001;
    const searchString = 'Jita';
    const expectedResults = {
      solar_system: [30000142],
      station: [60003760, 60003761],
      character: [555555555],
      corporation: [1344654522],
    };

    given('the ESI search endpoint is available with a broad search term', () => {
      jest
        .spyOn(client.search, 'characterSearch')
        .mockResolvedValue(expectedResults as any);
    });

    when('characterSearch is called with a broad query across all categories', async () => {
      result = await client.search.characterSearch(
        characterId,
        searchString,
        allCategories as any,
      );
    });

    then('the client shall return results spanning multiple categories', () => {
      expect(result).toBeDefined();
      expect(result.solar_system).toHaveLength(1);
      expect(result.solar_system).toContain(30000142);
      expect(result.station).toHaveLength(2);
      expect(result.character).toHaveLength(1);
      expect(result.corporation).toHaveLength(1);
    });
  });

  test('WHEN characterSearch finds no matches, the client shall return empty or undefined category arrays', ({ given, when, then }) => {
