    const characterId = 90000001;
    const searchString = 'xyznonexistent12345';
    const expectedResults = {};

    given('the ESI search endpoint is available but no data matches the query', () => {
      jest
        .spyOn(client.search, 'characterSearch')
        .mockResolvedValue(expectedResults as any);
    });

    when('characterSearch is called with a nonexistent search term', async () => {
      result = await client.search.characterSearch(
        characterId,
        searchString,
        allCategories as any,
      );
    });

    then('the client shall return undefined for all category arrays', () => {
      expect(result).toBeDefined();
      expect(result.solar_system).toBeUndefined();
      expect(result.station).toBeUndefined();
      expect(result.character).toBeUndefined();
      expect(result.corporation).toBeUndefined();
      expect(result.alliance).toBeUndefined();
    });
  });

  test('WHEN characterSearch is called for solar systems, the client shall return matching system IDs', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const searchString = 'Amarr';
    const expectedResults = {
      solar_system: [30002187, 30002188, 30002189],
    };

    given('the ESI search endpoint is available for solar system search', () => {
      jest
        .spyOn(client.search, 'characterSearch')
        .mockResolvedValue(expectedResults as any);
    });

    when('characterSearch is called with a solar system name', async () => {
      result = await client.search.characterSearch(
        characterId,
        searchString,
        allCategories as any,
      );
    });

    then('the client shall return matching solar system IDs', () => {
      expect(result).toBeDefined();
      expect(result.solar_system).toHaveLength(3);
      expect(result.solar_system).toContain(30002187);
    });
  });

  test('WHEN characterSearch is called for alliances, the client shall return matching alliance IDs', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const searchString = 'Goonswarm';
    const expectedResults = {
      alliance: [99005338],
    };

    given('the ESI search endpoint is available for alliance search', () => {
      jest
        .spyOn(client.search, 'characterSearch')
        .mockResolvedValue(expectedResults as any);
    });

    when('characterSearch is called with an alliance name', async () => {
      result = await client.search.characterSearch(
        characterId,
        searchString,
        allCategories as any,
      );
    });

    then('the client shall return matching alliance IDs', () => {
      expect(result).toBeDefined();
      expect(result.alliance).toHaveLength(1);
      expect(result.alliance).toContain(99005338);
    });
  });

  test('IF search permissions are insufficient, THEN the client shall throw an EsiError with status 403', ({ given, when, then }) => {
    let caughtError: any;
    const characterId = 90000001;
