      jest.spyOn(client.search, 'characterSearch').mockRejectedValue(error);
    });

    when('characterSearch is called without valid permissions', async () => {
      try {
        await client.search.characterSearch(characterId, searchString, [
          'character',
        ] as any);
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError indicating a 403 forbidden response', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN characterSearch is called with a short query, the client shall still return valid results', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const searchString = 'Ji';
